def route(match, confidence, th=0.75):
    if match and confidence >= th:
        return "자동 답변"
    return "사람 검토"

for m, c in [(True, 0.9), (True, 0.7), (False, 0.82)]:
    print(m, c, "->", route(m, c))

bm25 = ["A", "B", "C"]
vec = ["C", "A", "D"]

def rrf(*lists, k=60):
    sc = {}
    for l in lists:
        for i, d in enumerate(l):
            sc[d] = sc.get(d, 0) + 1 / (k + i + 1)
    return sorted(sc.items(), key=lambda x: -x[1])

for d, s in rrf(bm25, vec):
    print(d, round(s, 5))

gold = {"q1": "doc3", "q2": "doc7", "q3": "doc1"}
ranked = {"q1": ["doc3", "doc2", "doc9"],
          "q2": ["doc4", "doc7", "doc1"],
          "q3": ["doc5", "doc8", "doc2"]}

def recall_at(k):
    return sum(gold[q] in ranked[q][:k] for q in gold) / len(gold)

def mrr():
    s = 0
    for q in gold:
        r = ranked[q]
        s += 1 / (r.index(gold[q]) + 1) if gold[q] in r else 0
    return s / len(gold)

print("recall@1", round(recall_at(1), 3), "recall@3", round(recall_at(3), 3), "MRR", round(mrr(), 3))
